import csv
import json
from typing import List
from src.api.models import Article

class ArticleExporter:
    """Utility class to export articles to BibTeX, CSV, or JSON formats."""

    @staticmethod
    def to_bibtex(articles: List[Article], file_path: str) -> bool:
        """Export articles list to a BibTeX (.bib) file."""
        try:
            with open(file_path, "w", encoding="utf-8") as f:
                f.write(f"% Generated by SearchForLens ({len(articles)} entries)\n\n")
                for article in articles:
                    f.write(article.generate_bibtex())
                    f.write("\n\n")
            return True
        except Exception as e:
            print(f"Error exporting BibTeX: {e}")
            return False

    @staticmethod
    def to_csv(articles: List[Article], file_path: str) -> bool:
        """Export articles list to CSV file."""
        try:
            fieldnames = ["id", "title", "authors", "pub_date", "source", "citations", "arxiv_id", "bibcode", "doi", "url", "pdf_url", "journal", "abstract", "raw_bibtex"]
            with open(file_path, "w", encoding="utf-8", newline="") as f:
                writer = csv.DictWriter(f, fieldnames=fieldnames)
                writer.writeheader()
                for article in articles:
                    row = article.to_dict()
                    row["authors"] = "; ".join(article.authors)
                    writer.writerow(row)
            return True
        except Exception as e:
            print(f"Error exporting CSV: {e}")
            return False

    @staticmethod
    def to_json(articles: List[Article], file_path: str) -> bool:
        """Export articles list to formatted JSON file."""
        try:
            data = [article.to_dict() for article in articles]
            with open(file_path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
            return True
        except Exception as e:
            print(f"Error exporting JSON: {e}")
            return False
